const std = @import("std");
const net = std.net;
const http = std.http;
const json = std.json;
const Allocator = std.mem.Allocator;
const ArrayList = std.ArrayList;

// Import Core definition
const JaideCore = @import("../core/jaide_v42_5_core.zig");

pub const ServerConfig = struct {
    port: u16 = 8080,
    max_connections: usize = 1024,
    timeout_ms: u64 = 30000,
    thread_pool_size: usize = 8,
};

pub const InferenceRequest = struct {
    prompt: []const u8,
    max_new_tokens: usize = 128,
    temperature: f64 = 0.7,
    top_p: f64 = 0.9,
    stream: bool = false,
};

pub const InferenceResponse = struct {
    text: []const u8,
    finish_reason: []const u8,
    usage: struct {
        prompt_tokens: usize,
        completion_tokens: usize,
        total_tokens: usize,
    },
};

pub const Server = struct {
    allocator: Allocator,
    config: ServerConfig,
    core: *JaideCore.JaideCore,
    thread_pool: std.Thread.Pool,
    server: http.Server,

    pub fn init(allocator: Allocator, config: ServerConfig, core: *JaideCore.JaideCore) !*Server {
        const self = try allocator.create(Server);
        self.allocator = allocator;
        self.config = config;
        self.core = core;

        // Initialize Thread Pool for concurrent request handling
        try self.thread_pool.init(.{
            .allocator = allocator,
            .n_jobs = @as(u32, @intCast(config.thread_pool_size)),
        });

        // Initialize HTTP Server
        self.server = http.Server.init(allocator, .{ .reuse_address = true });

        return self;
    }

    pub fn deinit(self: *Server) void {
        self.thread_pool.deinit();
        self.server.deinit();
        self.allocator.destroy(self);
    }

    pub fn start(self: *Server) !void {
        const address = try net.Address.parseIp("0.0.0.0", self.config.port);
        try self.server.listen(address);

        std.debug.print(">> Jaide v42.5 Inference Server listening on port {d}...\n", .{self.config.port});

        while (true) {
            // Accept new connection
            // Note: In Zig 0.13+, accept logic might vary slightly, adhering to standard library patterns
            const res = self.server.accept(.{ .allocator = self.allocator }) catch |err| {
                std.debug.print("Accept error: {}\n", .{err});
                continue;
            };

            // Spawn task to handle request
            try self.thread_pool.spawn(handle_request_wrapper, .{ self, res });
        }
    }

    fn handle_request_wrapper(self: *Server, res: http.Server.Response) void {
        var response = res;
        defer response.deinit();

        self.handle_request(&response) catch |err| {
            std.debug.print("Request handling error: {}\n", .{err});
            if (response.state == .waited) {
               response.status = .internal_server_error;
               response.send() catch {};
            }
        };
    }

    fn handle_request(self: *Server, res: *http.Server.Response) !void {
        // Wait for headers
        try res.wait();

        // Basic routing
        if (std.mem.eql(u8, res.request.head.target, "/v1/chat/completions")) {
            return self.handle_inference(res);
        } else if (std.mem.eql(u8, res.request.head.target, "/health")) {
             res.status = .ok;
             try res.headers.append("Content-Type", "application/json");
             try res.do();
             try res.writeAll("{\"status\": \"healthy\", \"version\": \"42.5\"}");
             try res.finish();
             return;
        } else {
            res.status = .not_found;
            try res.do();
            try res.finish();
            return;
        }
    }

    fn handle_inference(self: *Server, res: *http.Server.Response) !void {
        // Read Body
        var body_buffer: [8192]u8 = undefined;
        const len = try res.readAll(&body_buffer);
        const body = body_buffer[0..len];

        // Parse JSON
        const parsed = try json.parseFromSlice(InferenceRequest, self.allocator, body, .{ .ignore_unknown_fields = true });
        defer parsed.deinit();
        const req = parsed.value;

        // --- CRITICAL PATH: CORE INFERENCE ---
        // Lock core if necessary (assuming core is thread-safe internally or we lock here)
        // Here we assume JaideCore.forward is thread-safe or stateless enough.

        const output_text_owned = try self.core.forward(req.prompt); 
        // Note: forward returns []const u8, but likely allocated. 
        // In the real system, we need to ensure memory ownership. 
        // For this serialization, we assume Core manages a buffer or returns a literal.

        // Construct Response Object
        const response_data = InferenceResponse{
            .text = output_text_owned,
            .finish_reason = "stop",
            .usage = .{
                .prompt_tokens = req.prompt.len / 4, // Rough estimate
                .completion_tokens = output_text_owned.len / 4,
                .total_tokens = (req.prompt.len + output_text_owned.len) / 4,
            },
        };

        // Serialize Response
        var response_string = ArrayList(u8).init(self.allocator);
        defer response_string.deinit();
        try json.stringify(response_data, .{}, response_string.writer());

        // Send HTTP Response
        res.status = .ok;
        try res.headers.append("Content-Type", "application/json");
        try res.do();
        try res.writeAll(response_string.items);
        try res.finish();
    }
};

